                .skip(offset)
                .limit(limit)
                .toList();
        queryLog.recordPage(offset, limit, page.size());
        return page;
    }

    /** Returns the number of customers matching {@code filter}. */
    public int count(CustomerFilter filter) {
        int total = matching(filter).size();
        queryLog.recordCount(total);
        return total;
    }

    private List<Customer> matching(CustomerFilter filter) {
        List<String> terms = filter.nameTerms();
        return customers.stream()
                .filter(c -> filter.matchesStatus(c.status()))
                .filter(c -> matchesName(c, terms))
                .toList();
    }

