        if (terms.isEmpty()) {
            return true;
        }
        String first = CustomerFilter.normalize(customer.firstName());
        String last = CustomerFilter.normalize(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
