+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter over the customer list.
+ *
+ * @param name      free text; split on whitespace into terms that must all
+ *                  appear, case- and accent-insensitively, as a substring of
+ *                  the first name or the last name. Blank means "no filter".
+ * @param statuses  statuses to restrict to; empty means "every status"
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** The name filter, split into normalized, non-blank search terms. */
+    public List<String> nameTerms() {
+        String trimmed = name.trim();
+        if (trimmed.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(WHITESPACE.split(trimmed)).map(CustomerFilter::normalize).toList();
+    }
+
+    public boolean matchesStatus(CustomerStatus status) {
+        return statuses.isEmpty() || statuses.contains(status);
+    }
+
+    /** Lower-cases and strips accents, so matching ignores both. */
+    static String normalize(String s) {
+        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
